  "devdoc": {
    "kind": "dev",
    "methods": {
      "constructor": {
        "params": {
          "_draftsImplementation": "The first drafts implementation.",
          "_ownerHistoryImplementation": "The first owner-history implementation.",
          "_protocolSafe": "The safe the records implementation must answer. Not        checked for code: it is an address the implementation compares,        not an authority in this factory."
        }
      },
      "createRecordsModule(address)": {
        "details": "One records module per Safe, which is why the salt carries no nonce:      the address depends only on (this factory, role, safe) and the      current implementation's init code. The mapping makes a retry      idempotent — it returns the recorded module and writes nothing.      The proxy is deployed with an empty initializer because the records      module requires the factory as `msg.sender` in `initialize`. The      factory calls `initialize(safe, \"\")` immediately after, in the same      transaction, so no uninitialised module can be left behind; a failed      initializer reverts the whole create with `InitializerFailed`.      Reverts `NoImplementation` when nothing is set."
      },
      "getDraftsModulesForSafe(address)": {
        "details": "An index, not proof — see the contract docblock."
      },
      "getOwnerHistoryModulesForSafe(address)": {
        "details": "An index, not proof — see the contract docblock."
      },
      "isApproved(bytes32,address)": {
        "details": "Read by the records module's `_authorizeUpgrade` at the moment of an      upgrade, so a module can move only to what the deployer set. Exactly      one implementation is approved per kind at a time; setting a new one      makes it the only target."
      },
      "latestImplementation(bytes32)": {
        "details": "Lets the records implementation's deploy script and any reader that      knows this factory and the kind hash ask the same question they ask      a multi-kind factory."
      },
      "setRecordsImplementation(address)": {
        "details": "Only the deployer. Three declarations are read from the candidate:      `factory()` must name this factory, `moduleKind()` must equal      `RECORDS_KIND`, and `proxiableUUID()` must answer the ERC-1967 slot.      The first stops an implementation gated elsewhere from entering this      set; the second stops another kind's code being handed to the      records module; the third guarantees an upgrade door.      Existing modules keep their address and keep running their current      implementation. The new one is where future creates go and a legal      upgrade target for existing modules."
      }
    },
    "stateVariables": {
      "DRAFTS_ROLE": {
        "details": "Salt domains. One constant per role so a drafts proxy, a history      proxy and a records proxy for the same Safe never collide."
      },
      "ERC1967_IMPLEMENTATION_SLOT": {
        "details": "`keccak256(\"eip1967.proxy.implementation\") - 1`, what every UUPS      implementation returns from `proxiableUUID()`."
      },
      "createNonce": {
        "details": "Creates started so far, per Safe and role. A counter, not a      nonce that a caller can choose: `create*Module` takes the next      value and increments it once the deployment has succeeded."
      },
      "draftsModules": {
        "details": "Proxies this factory created, per Safe — **an index, not proof**.      Creation is permissionless, so anyone can push an entry for any Safe      here; read it only against the Safe's own adoption record."
      },
      "guards": {
        "details": "The guard this factory deployed for a history proxy, or      `address(0)`. An index again: it says what was deployed, not what      the Safe installed."
      },
      "recordsModule": {
        "details": "The records module this factory deployed for a Safe, or `address(0)`.      One per Safe: `createRecordsModule` returns this before it deploys,      so a retry costs nothing and the address never moves."
      }
    },
    "title": "AuthorFactory",
    "version": 1
  },
